module rffe_register(
  input  logic clk,
  input  logic rst_n,
  input  logic sclk,
  input  logic sdata,
  output logic sdata_out,
  output logic sdata_oe
);

  // ------------------------------------------------------------------
  // Clock-domain: sclk is an input pin; treat sclk as a clock.
  // SCLK = 1 MHz, clk = 500 MHz.  Synchronizer not needed for a
  // simple digital model, but use clk aligned sampling on sclk edges.
  // ------------------------------------------------------------------

  // Edge detectors run on clk.
  logic sclk_ff, sdata_ff;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      sclk_ff <= 1'b0;
      sdata_ff <= 1'b0;
    end else begin
      sclk_ff <= sclk;
      sdata_ff <= sdata;
    end
  end

  wire sclk_rise = (sclk & ~sclk_ff);
  wire sclk_fall = (~sclk & sclk_ff);

  // ------------------------------------------------------------------
  // Receive state machine
  // ------------------------------------------------------------------
  // phases:
  //   0 : idle, waiting for SSC (sdata=1 while sclk idle low)
  //   1 : receiving 4-bit USID
  //   2 : receiving 8-bit command
  //   3 : receiving 1-bit parity
  //   4 : write -- receiving 8-bit data
  //   5 : write -- receiving 1-bit parity, then bus park
  //   6 : read  -- master bus park, then drive data
  //   7 : read  -- driving 8-bit data
  //   8 : read  -- driving parity
  //   9 : read  -- bus park (release after)
  localparam [3:0] IDLE=0, USID=1, CMD=2, CPAR=3, WDATA=4, WPAR=5,
                   RPARK=6, RDATA=7, RPAR=8, RBPARK=9;

  logic [3:0] state;
  logic [3:0] bitcnt;
  logic [3:0] usid_sh;
  logic [7:0] cmd_sh;
  logic       cpar_sh;
  logic [7:0] wdata_sh;
  logic       wpar_sh;

  logic [7:0] regs [0:15];
  integer i;

  // Parallel output shift register (for read)
  logic [7:0] rd_data;
  logic       rd_par;

  reg sdata_out_r;
  reg sdata_oe_r;

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state      <= IDLE;
      bitcnt     <= 4'd0;
      usid_sh    <= 4'd0;
      cmd_sh     <= 8'd0;
      cpar_sh    <= 1'b0;
      wdata_sh   <= 8'd0;
      wpar_sh    <= 1'b0;
      rd_data    <= 8'd0;
      rd_par     <= 1'b0;
      sdata_out_r<= 1'b0;
      sdata_oe_r <= 1'b0;
      for (i = 0; i < 16; i = i + 1) regs[i] <= 8'hFF;
    end else begin
      // default: keep outputs
      case (state)
        IDLE: begin
          if (sclk_rise) begin
            // SSC detected on first rising edge with sdata=1
            if (sdata_ff) begin
              state   <= USID;
              bitcnt  <= 4'd0;
              usid_sh <= 4'd0;
            end
          end
        end

        USID: begin
          if (sclk_rise) begin
            usid_sh <= {usid_sh[2:0], sdata_ff};
            if (bitcnt == 4'd3) begin
              state  <= CMD;
              bitcnt <= 4'd0;
              cmd_sh <= 8'd0;
            end else begin
              bitcnt <= bitcnt + 4'd1;
            end
          end
        end

        CMD: begin
          if (sclk_rise) begin
            cmd_sh <= {cmd_sh[6:0], sdata_ff};
            if (bitcnt == 4'd7) begin
              state  <= CPAR;
              bitcnt <= 4'd0;
              cpar_sh <= 1'b0;
            end else begin
              bitcnt <= bitcnt + 4'd1;
            end
          end
        end

        CPAR: begin
          if (sclk_rise) begin
            // decide type from command
            // 0x40..0x4F write, 0x60..0x6F read
            if (cmd_sh[7:5] == 3'b010) begin
              state   <= WDATA;
              bitcnt  <= 4'd0;
              wdata_sh<= 8'd0;
            end else if (cmd_sh[7:5] == 3'b011) begin
              state   <= RPARK;
              bitcnt  <= 4'd0;
            end else begin
              state   <= IDLE;
            end
          end
        end

        WDATA: begin
          if (sclk_rise) begin
            wdata_sh <= {wdata_sh[6:0], sdata_ff};
            if (bitcnt == 4'd7) begin
              state   <= WPAR;
              bitcnt  <= 4'd0;
            end else begin
              bitcnt <= bitcnt + 4'd1;
            end
          end
        end

        WPAR: begin
          if (sclk_rise) begin
            // commit write at parity edge (end of frame)
            if (cmd_sh[4:0] <= 5'd15) begin
              regs[cmd_sh[3:0]] <= regs[cmd_sh[3:0]] & ~wdata_sh;
            end
            // wait for bus park falling edges / return idle
            state  <= IDLE;
            bitcnt <= 4'd0;
          end
        end

        RPARK: begin
          // master drives bus park (0) on first rising edge
          if (sclk_rise) begin
            if (cmd_sh[4:0] <= 5'd15) begin
              rd_data <= regs[cmd_sh[3:0]];
              rd_par  <= ~(^regs[cmd_sh[3:0]]);
              sdata_out_r <= regs[cmd_sh[3:0]][7];
              sdata_oe_r  <= 1'b1;
            end
            state  <= RDATA;
            bitcnt <= 4'd0;
          end
        end

        RDATA: begin
          if (sclk_fall) begin
            // shift to next bit; drive next data bit after falling edge
            if (bitcnt == 4'd7) begin
              sdata_out_r <= rd_par;
              state       <= RPAR;
            end else begin
              sdata_out_r <= rd_data[6 - bitcnt];
              bitcnt      <= bitcnt + 4'd1;
            end
          end
        end

        RPAR: begin
          if (sclk_fall) begin
            sdata_out_r <= 1'b0;
            state       <= RBPARK;
          end
        end

        RBPARK: begin
          if (sclk_rise) begin
            // bus park sampled as 0; release after falling edge
            state <= IDLE;
          end
          if (sclk_fall) begin
            sdata_oe_r <= 1'b0;
          end
        end

        default: state <= IDLE;
      endcase
    end
  end

  assign sdata_out = sdata_out_r;
  assign sdata_oe  = sdata_oe_r;

endmodule
